 public static final int CAMERA_CHASE=0,CAMERA_REAR=1,CAMERA_RIGHT_QUARTER=2,CAMERA_LEFT_QUARTER=3;private final R r;private final FlightSoundEngine sound=new FlightSoundEngine();private float sndThrottle=.6f,sndGear=1f,sndBrake;private boolean sndGround=true;
 public Jet3DView(Context c){super(c);setEGLContextClientVersion(2);setEGLConfigChooser(8,8,8,8,16,0);getHolder().setFormat(PixelFormat.TRANSLUCENT);setZOrderOnTop(true);r=new R();setRenderer(r);setRenderMode(RENDERMODE_CONTINUOUSLY);setPreserveEGLContextOnPause(true);}public void setTelemetry(float a,float b,float c,float d,float e,int x,boolean live){r.tele(a,b,c,d,live);sndThrottle=Math.max(0,Math.min(1,d));sound.update(sndThrottle,Math.max(0,sndThrottle*230),sndGear,sndBrake,sndGround);}public void setSimulationState(float g,float mc,float nc,float b,boolean ground){r.sim(g,mc,nc);sndGear=g;sndBrake=b;sndGround=ground;sound.update(sndThrottle,Math.max(0,sndThrottle*230),sndGear,sndBrake,sndGround);}public void setWheelSpeed(float mps){r.ws=Math.max(0,mps);}public void setCameraMode(int m){r.cam=Math.max(0,Math.min(3,m));}public int getCameraMode(){return r.cam;}public boolean onTouchEvent(MotionEvent e){if(e.getAction()==1)r.cam=(r.cam+1)%4;return true;}public void onResume(){super.onResume();sound.start();}public void onPause(){sound.stop();super.onPause();}
