 static final String VS="uniform mat4 uMvp,uModel;uniform float uThrottle,uGear,uMainComp,uNoseComp,uWheelSpin;attribute vec3 aPos,aNormal;attribute float aPart;varying vec3 vN;varying float vP,vR;mat2 rr(float a){float c=cos(a),s=sin(a);return mat2(c,-s,s,c);}void main(){vec3 p=aPos,n=aNormal;vR=0.;if(aPart>12.5&&aPart<15.5||aPart>23.5&&aPart<24.5){float nose=step(p.z,-2.),r=1.-uGear,fold=smoothstep(.04,.88,r);vR=r;if(aPart>13.5&&aPart<14.5&&uGear>.55){vec2 ctr=nose>.5?vec2(-1.70,-3.72):vec2(-1.72,1.12);p.yz=rr(uWheelSpin)*(p.yz-ctr)+ctr;}if(nose>.5){vec2 piv=vec2(-.48,-3.70),q=p.yz-piv;q=rr(-1.40*fold)*q;p.yz=piv+q;p.x*=mix(1.,.5,fold);p.y=min(p.y,-.36);}else{float s=p.x<0.?-1.:1.;vec2 piv=vec2(1.36*s,-.38),q=vec2(p.x,p.y)-piv;q=rr(-s*1.20*fold)*q;p.x=piv.x+q.x;p.y=piv.y+q.y;p.x=mix(p.x,.68*s,smoothstep(.70,.98,r));p.z=mix(p.z,.88+(p.z-.88)*.38,fold);p.y=min(p.y,-.34);}if(aPart>14.5&&aPart<15.5){float op=smoothstep(.02,.2,r)*(1.-smoothstep(.70,.98,r));p.x+=(p.x<0.?-.28:.28)*op;p.y-=.10*op;}}vN=normalize(mat3(uModel)*n);vP=aPart;gl_Position=uMvp*vec4(p,1.);}";
